# ---------------------------------------------------------------- русские версии помощников make_manuals.py
def kmh(ms): return f'{ms:.0f} км/ч'


def modes_table(name, cap, with_increased=True):
    s = SETS[name]
    idx = [0, 1, 3] if with_increased else [0, 1]
    heads = ['', 'Low', 'Reduced'] + (['Increased'] if with_increased else [])
    rows = [['Сцепление на грунте'] + [x(s[i]['dirt']) for i in idx], ['Сцепление на гравии'] + [x(s[i]['gravel']) for i in idx],
            ['Сцепление на песке'] + [x(s[i]['sand']) for i in idx], ['Сцепление на камнях'] + [x(s[i]['rock']) for i in idx],
            ['Сцепление на асфальте'] + [x(s[i]['asphalt']) for i in idx], ['Сцепление в грязи'] + [x(s[i]['mud']) for i in idx],
            ['Радиус шины, до'] + [f'на {s[i]["offset"] * 100:g} см меньше' if s[i]['offset'] else 'без изменений' for i in idx],
            ['Расход топлива в движении'] + [x(s[i]['fuel']) for i in idx], ['Скорость поворота руля'] + [x(s[i]['steer']) for i in idx],
            ['Износ начинается выше'] + [kmh(s[i]['minv']) if s[i]['maxd'] else 'без износа' for i in idx],
            ['Наибольший износ с'] + [kmh(s[i]['maxv']) if s[i]['maxd'] else '' for i in idx],
            ['Повреждение на колесо'] + [f'от {s[i]["mind"]:g} до {s[i]["maxd"]:g}' if s[i]['maxd'] else '' for i in idx],
            ['Каждые'] + [f'{s[i]["tick"]:g} с' if s[i]['maxd'] else '' for i in idx]]
    return table(heads, rows, cap)


def temp_table():
    rows = []
    for c in [-40, -30, -20, -10, 0, 10, 15, 25, 35, 45]:
        e = effect(c)
        lab = f'{c} °C' if c != 15 else '15 °C (опорная)'
        rows.append([lab, f'{air(1.0, c) * 100:.0f}%', f'{air(0.45, c) / 0.45 * 100:.0f}%', x(e['hard']), x(e['soft']), x(e['speed'])])
    return table(['На улице', 'Normal держит', 'Low держит (от своего)', 'Асфальт и камни', 'Грунт, гравий, песок, грязь', 'Скорости износа'], rows,
                 'Что делает температура воздуха')


def balance_table():
    rows = []
    for name, (g, a, m) in [('Сильная модовая шина', (4.5, 5.0, 4.0)), ('Модовый Урал', (3.55, 3.5, 2.8)),
                            ('Грязевая шина, сильная только в грязи', (2.0, 0.6, 5.0)), ('Любая ванильная шина', (2.2, 2.6, 1.3))]:
        cells = [f'{name} ({g:g} / {a:g} / {m:g})']
        for s in [0.5, 1.0, 1.5, 2.0]:
            k = balance(g, a, m, s)
            cells.append(f'{x(k)} <span class="dim">{g * k:.2f} / {a * k:.2f} / {m * k:.2f}</span>')
        rows.append(cells)
    return table(['Шина (грунт / асфальт / грязь)', 'Сила 0.5', '1', '1.5', '2'], rows, 'Баланс по ванильным шинам при разной силе', 'wide')


